import test from 'node:test';
import assert from 'node:assert/strict';
import * as transport from '../../src/propose/foottrace-transport.mjs';
import {identityFactsFixture} from './identity-facts-fixture.mjs';
const repository={id:123,full_name:'footprintjs/foottrace'},sha='a'.repeat(40),other='b'.repeat(40),PRIVATE='PRIVATE-PROPOSAL-EFFECT';
const payloads={
 'create-blob':{content:'exact generated bytes',encoding:'utf-8'},
 'create-tree':{base_tree:sha,tree:[{path:'package.json',mode:'100644',type:'blob',sha:other}]},
 'create-commit':{message:'chore: release 1.11.1',tree:sha,parents:[other,'c'.repeat(40)]},
 'move-ref':{sha,force:false},
 'create-pr':{title:'Release 1.11.1',head:'release/next',base:'main',body:'exact computed notes'}
};
const routes={'create-blob':'git/blobs','create-tree':'git/trees','create-commit':'git/commits','move-ref':'git/refs/heads/release/next','create-pr':'pulls'};
function ensure(){assert.equal(typeof transport.foottraceProposalEffectPort,'function','closed same-owner nonforce proposal effects are missing');return transport.foottraceProposalEffectPort;}
function fixture({status,reply,limits,inspection=false}={}){
 const calls=[],owner=(inspection?transport.createFoottraceInspectionTransport:transport.createFoottraceTransport)({
  repository,limits,token:'offline_sealed_proposal_writer',appIdentity:{slug:'agentfootprint-release',clientId:'offline-client',facts:identityFactsFixture()},
  fetcher:async(url,options)=>{
   calls.push({url,method:options.method,body:options.body,authorization:options.headers.authorization});
   if(reply)return reply(url,options);
   return Response.json({sha,number:43},{status:status??(options.method==='POST'?201:200)});
  }
 });
 const port=ensure();
 return {owner,calls,read:transport.foottraceTransportPort(owner),
  effect:(effect,payload=payloads[effect])=>port(owner,{effect,payload})};
}
for(const effect of Object.keys(payloads))test('native '+effect+' uses only its exact bound route/body on SAME captured writer owner',async()=>{
 const f=fixture();let p;assert.doesNotThrow(()=>{p=f.effect(effect);});assert.equal(p.authorized,false);assert.equal(p.scope,'exact-proposal-effect-io-only');
 assert.equal(Object.hasOwn(p,'api'),false);assert.equal(Object.hasOwn(p,'fetch'),false);
 assert.equal(p.observation().state,'not-attempted');let result;await assert.doesNotReject(async()=>{result=await p.submit();});assert.deepEqual(result,{data:{sha,number:43}});
 assert.equal(p.observation().state,'returned');assert.equal(p.observation().reconciled,false);
 assert.equal(f.calls[0].url,'https://api.github.com/repos/footprintjs/foottrace/'+routes[effect]);
 assert.equal(f.calls[0].method,effect==='move-ref'?'PATCH':'POST');
 assert.deepEqual(JSON.parse(f.calls[0].body),payloads[effect]);
 assert.equal(f.calls[0].authorization,'Bearer offline_sealed_proposal_writer');
 assert.equal(JSON.stringify(p).includes('offline_sealed_proposal_writer'),false);
 await f.read.api('GET','/repos/footprintjs/foottrace/pulls/43');
 assert.equal(f.calls[1].authorization,f.calls[0].authorization);
 await assert.rejects(()=>f.effect(effect).submit());assert.equal(f.calls.length,2);
});
for(const [label,effect,change] of [
 ['force ref','move-ref',p=>p.force=true],['ref route override','move-ref',p=>p.ref='heads/main'],
 ['custom commit author','create-commit',p=>p.author={name:PRIVATE}],['custom signature','create-commit',p=>p.signature=PRIVATE],
 ['duplicate commit parents','create-commit',p=>p.parents=[other,other]],
 ['foreign PR head','create-pr',p=>p.head='foreign:main'],['foreign PR base','create-pr',p=>p.base='other'],
 ['auto merge field','create-pr',p=>p.auto_merge=true],['unsafe tree path','create-tree',p=>p.tree[0].path='../private'],
 ['duplicate tree path','create-tree',p=>p.tree.push({...p.tree[0]})],['symlink mode','create-tree',p=>p.tree[0].mode='120000'],
 ['invalid blob encoding','create-blob',p=>p.encoding='base64']
])test(label+' refuses before provider IO',()=>{
 const f=fixture(),p=structuredClone(payloads[effect]);assert.doesNotThrow(()=>f.effect(effect));change(p);assert.throws(()=>f.effect(effect,p));assert.equal(f.calls.length,0);
});
test('inspection owner and saved transport fields cannot derive nonforce submission ports',()=>{
 const f=fixture({inspection:true});assert.throws(()=>f.effect('create-commit'));
 assert.throws(()=>ensure()({readOnly:false},{effect:'move-ref',payload:payloads['move-ref']}));assert.equal(f.calls.length,0);
});
test('different commit/ref/PR payloads cannot repeat a singleton effect in one owner',async()=>{
 const f=fixture();await f.effect('create-commit').submit();
 await assert.rejects(()=>f.effect('create-commit',{...payloads['create-commit'],message:'another bounded message'}).submit());
 assert.equal(f.calls.length,1);
});
test('distinct blobs are allowed but identical content cannot reset an attempted blob through another port',async()=>{
 const f=fixture();await f.effect('create-blob').submit();
 await assert.doesNotReject(()=>f.effect('create-blob',{content:'other generated bytes',encoding:'utf-8'}).submit());
 await assert.rejects(()=>f.effect('create-blob').submit());assert.equal(f.calls.length,2);
});
for(const status of [401,403,202,200])test('POST '+status+' is rejected/technical and never reconciled',async()=>{
 const f=fixture({status}),p=f.effect('create-commit');await assert.rejects(()=>p.submit());
 assert.equal(p.observation().state,status<200||status>=400?'rejected':'failed');assert.equal(p.observation().reconciled,false);
 await assert.rejects(()=>f.effect('move-ref').submit());assert.equal(f.calls.length,1);
});
test('uncertain non-idempotent submission stops ALL further mutations on this owner and leaves GET verification available',async()=>{
 const f=fixture({reply:(url,o)=>o.method==='GET'?Response.json({sha}):new Response(PRIVATE,{status:503})});
 const first=f.effect('create-commit'),second=f.effect('move-ref');await assert.rejects(()=>first.submit());
 assert.equal(first.observation().state,'uncertain');
 await assert.rejects(()=>second.submit());
 await assert.rejects(()=>transport.foottraceMetadataPatchPort(f.owner,{pullNumber:43,desired:{title:'Release 1.11.1',body:'exact'}}).setExact());
 assert.equal(f.calls.length,1);assert.deepEqual(await f.read.api('GET','/repos/footprintjs/foottrace/git/commits/'+sha),{data:{sha}});
 assert.equal(f.calls.length,2);assert.equal(JSON.stringify(first.observation()).includes(PRIVATE),false);
});
test('a returned malformed JSON response is technical, not network uncertainty; subsequent mutations remain stopped',async()=>{
 const f=fixture({reply:()=>new Response(PRIVATE,{status:201,headers:{'content-type':'application/json'}})}),p=f.effect('create-tree');
 await assert.rejects(()=>p.submit());assert.equal(p.observation().state,'returned');
 await assert.rejects(()=>f.effect('create-commit').submit());assert.equal(f.calls.length,1);
});
test('actual request body bytes must fit the SAME global bank before fetch',async()=>{
 const f=fixture({limits:{requests:8,totalBytes:8}}),p=f.effect('create-blob');
 await assert.rejects(()=>p.submit());assert.equal(f.calls.length,0);assert.equal(f.read.transportFacts().exhausted,true);
 assert.equal(p.observation().state,'not-attempted');
});
test('payload bytes are detached and canonical before any await',async()=>{
 const f=fixture(),payload=structuredClone(payloads['create-commit']),p=f.effect('create-commit',payload);
 payload.parents.reverse();payload.message=PRIVATE;await p.submit();
 assert.deepEqual(JSON.parse(f.calls[0].body),payloads['create-commit']);
});
test('rich payload getters and unknown effect names never acquire the provider',()=>{
 const f=fixture();let reads=0;
 assert.throws(()=>f.effect('constructor',{}));
 assert.throws(()=>f.effect('create-blob',{get content(){reads++;return PRIVATE;},encoding:'utf-8'}));
 assert.equal(reads,0);assert.equal(f.calls.length,0);
});

test('native blob typed admission supports bounded UTF8 beyond the ledger JSON ceiling without raising that ceiling',async()=>{
 const f=fixture(),content='🧪'.repeat(300000),p=f.effect('create-blob',{content,encoding:'utf-8'});
 await p.submit();assert.equal(JSON.parse(f.calls[0].body).content,content);
});
test('oversized or ill-formed blob content refuses before IO',()=>{
 const f=fixture();assert.doesNotThrow(()=>f.effect('create-blob'));
 for(const content of ['x'.repeat(2*1024*1024+1),'\ud800'])assert.throws(()=>f.effect('create-blob',{content,encoding:'utf-8'}));
 assert.equal(f.calls.length,0);
});

test('the underlying owner also stops mutation after a narrowly uncertain fetch, before any new view can submit',async()=>{
 const {createGitHubTransport}=await import('../../src/propose/github-transport.mjs');let calls=0;
 const owner=createGitHubTransport({repository,fetcher:async()=>{
  calls++;if(calls===1)throw new TypeError('fetch failed',{cause:{code:'ECONNRESET'}});
  return Response.json({sha});
 }});
 const first=owner.createExactProposalEffectView({effect:'create-commit',payload:payloads['create-commit']});
 await assert.rejects(()=>first.fetch('https://api.github.com/repos/footprintjs/foottrace/git/commits',{method:'POST',body:JSON.stringify(payloads['create-commit'])}));
 assert.equal(first.observation().state,'uncertain');
 const next=owner.createExactProposalEffectView({effect:'move-ref',payload:payloads['move-ref']});
 await assert.rejects(()=>next.fetch('https://api.github.com/repos/footprintjs/foottrace/git/refs/heads/release/next',{method:'PATCH',body:JSON.stringify(payloads['move-ref'])}));
 assert.equal(calls,1);
});
test('same singleton locks before pending fetch and refuses concurrent changed-payload submissions',async()=>{
 let release;const pending=new Promise(resolve=>{release=resolve;});
 const f=fixture({reply:()=>pending}),first=f.effect('create-commit').submit();let duplicate='pending';
 const next=f.effect('create-commit',{...payloads['create-commit'],message:'another message'}).submit().then(()=>{duplicate='resolved';},()=>{duplicate='rejected';});
 await new Promise(resolve=>setImmediate(resolve));
 try{assert.equal(duplicate,'rejected');assert.equal(f.calls.length,1);}
 finally{release(Response.json({sha},{status:201}));await first;await next;}
});

test('tree payloads detach and canonicalize path order without exposing request data as permission',async()=>{
 const f=fixture(),payload={base_tree:sha,tree:[
  {path:'z.txt',mode:'100644',type:'blob',sha:other},{path:'a.txt',mode:'100755',type:'blob',sha}
 ]},p=f.effect('create-tree',payload);payload.tree[0].path='../changed';
 await assert.doesNotReject(()=>p.submit());
 assert.deepEqual(JSON.parse(f.calls[0].body).tree.map(row=>row.path),['a.txt','z.txt']);
 assert.equal(p.observation().authorized,false);assert.equal(p.observation().reconciled,false);
});
test('native effect views cannot reset an exhausted shared GET request bank',async()=>{
 const f=fixture({limits:{requests:1,totalBytes:1024}});await f.read.api('GET','/repos/footprintjs/foottrace/pulls/43');
 const p=f.effect('create-commit');await assert.rejects(()=>p.submit());
 assert.equal(f.calls.length,1);assert.equal(f.read.transportFacts().exhausted,true);
});

for(const status of [401,403,404,409,422,429,501,505])test('direct native owner halts ALL mutation views after HTTP '+status+' while permitting GET verification',async()=>{
 const {createGitHubTransport}=await import('../../src/propose/github-transport.mjs');let calls=0;
 const owner=createGitHubTransport({repository,fetcher:async(url,options)=>{
  calls++;return calls===1?new Response(PRIVATE,{status}):Response.json({sha},{status:options.method==='POST'?201:200});
 }});
 const first=owner.createExactProposalEffectView({effect:'create-commit',payload:payloads['create-commit']});
 const response=await first.fetch('https://api.github.com/repos/footprintjs/foottrace/git/commits',
  {method:'POST',body:JSON.stringify(payloads['create-commit'])});
 assert.equal(response.status,status);assert.equal(await response.text(),'');
 assert.equal(first.observation().state,status<500?'rejected':'failed');
 const next=owner.createExactProposalEffectView({effect:'move-ref',payload:payloads['move-ref']});
 await assert.rejects(()=>next.fetch('https://api.github.com/repos/footprintjs/foottrace/git/refs/heads/release/next',
  {method:'PATCH',body:JSON.stringify(payloads['move-ref'])}));
 const desired={title:'Release 1.11.1',body:'exact'},metadata=owner.createExactPatchView({pullNumber:43,desired});
 await assert.rejects(()=>metadata.fetch('https://api.github.com/repos/footprintjs/foottrace/pulls/43',
  {method:'PATCH',body:JSON.stringify(desired)}));assert.equal(calls,1);
 await owner.createView().fetch('https://api.github.com/repos/footprintjs/foottrace/git/commits/'+sha,{method:'GET'});
 assert.equal(calls,2);
});
